    @Select("SELECT * FROM reading_tasks WHERE user_id = #{userId} ORDER BY created_at DESC, id DESC")
    List<ReadingTask> findByUserId(Long userId);

    @Select("SELECT * FROM reading_tasks WHERE id = #{id}")
    ReadingTask findById(Long id);

    @Update("UPDATE reading_tasks SET status = #{status}, updated_at = #{updatedAt} WHERE id = #{id}")
    int updateStatus(@Param("id") Long id, @Param("status") String status, @Param("updatedAt") LocalDateTime updatedAt);

    @Delete("<script>"
            + "DELETE FROM reading_tasks WHERE id IN "
            + "<foreach collection='ids' item='taskId' open='(' separator=',' close=')'>#{taskId}</foreach>"
            + "</script>")
