        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setEmail(email);
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.of(2024, 6, 1, 10, 0, 0));
        userMapper.insert(user);
    }
